// SubmitCapture is the resolver for the submitCapture field.
func (r *mutationResolver) SubmitCapture(ctx context.Context, input graphql1.SubmitCaptureInput) (*graphql1.SubmissionPayload, error) {
	tenantID, responsibilityID, err := r.externalResponsibility(ctx)
	if err != nil {
		// A successful submit completes the invitation and revokes its write
		// session. Permit a retry through the completed-capture read session;
		// the submit command returns the existing immutable submission.
		if _, hasExternalCredentials := requestctx.ExternalCredentialsFromContext(ctx); !hasExternalCredentials {
			return nil, err
		}
		tenantID, responsibilityID, err = r.externalCaptureReadResponsibility(ctx)
		if err != nil {
			return nil, err
		}
	}
	raw, err := r.Bus.Send(ctx, capturesubmit.Command{TenantID: tenantID, ResponsibilityID: responsibilityID, ConfirmIncomplete: input.ConfirmIncomplete, ClientMutationID: input.ClientMutationID})
	if err != nil {
		return nil, err
	}
	submission := raw.(database.SubmissionVersion)
	preparationPending, err := submissionPreparationPending(ctx, r.DB, tenantID, submission)
	if err != nil {
		return nil, err
	}
	return &graphql1.SubmissionPayload{Submission: &graphql1.Submission{ID: submission.ID.String(), Complete: submission.Complete, RequiresAttention: submission.RequiresAttention, PreparationPending: preparationPending, SubmittedAt: submission.SubmittedAt.Format(time.RFC3339Nano)}, UserErrors: []*graphql1.UserError{}, ClientMutationID: input.ClientMutationID}, nil
}

// RequestRecapture is the resolver for the requestRecapture field.
func (r *mutationResolver) RequestRecapture(ctx context.Context, input graphql1.RequestRecaptureInput) (*graphql1.RecapturePayload, error) {
	meta, ok := requestctx.FromContext(ctx)
	if !ok {
		return nil, unauthenticated()
	}
	inspectionID, err := identity.ParseID(input.InspectionID)
	if err != nil {
		return nil, invalidID("inspectionId")
	}
	deadline, err := time.Parse(time.RFC3339, input.DeadlineAt)
	if err != nil {
		return nil, graphql1Error("deadlineAt")
	}
	items := make([]recapturecore.Item, 0, len(input.Items))
	for _, item := range input.Items {
		var original *identity.ID
		if item.OriginalMediaID != nil {
			id, e := identity.ParseID(*item.OriginalMediaID)
			if e != nil {
				return nil, invalidID("originalMediaId")
			}
			original = &id
		}
		items = append(items, recapturecore.Item{RequirementKey: item.RequirementKey, OriginalMediaID: original, Reason: item.Reason})
	}
	raw, err := r.Bus.Send(ctx, recapturerequest.Command{Input: recapturecore.RequestInput{TenantID: meta.TenantID, InspectionID: inspectionID, Items: items, DeadlineAt: deadline, IdempotencyKey: input.ClientMutationID}})
	if err != nil {
		return nil, err
	}
	created := raw.(recapturecore.Result)
	if err := recordTriageRecaptureRequest(ctx, r.DB, meta, inspectionID, input.ClientMutationID); err != nil {
		return nil, err
	}
	return &graphql1.RecapturePayload{Recapture: &graphql1.Recapture{ID: created.RequestID.String(), ResponsibilityID: created.ResponsibilityID.String(), Status: created.Status, DeadlineAt: &input.DeadlineAt}, UserErrors: []*graphql1.UserError{}, ClientMutationID: input.ClientMutationID}, nil
}

