// SubmitRecapture is the resolver for the submitRecapture field.
func (r *mutationResolver) SubmitRecapture(ctx context.Context, input graphql1.SubmitRecaptureInput) (*graphql1.RecapturePayload, error) {
	requestID, err := identity.ParseID(input.RequestID)
	if err != nil {
		return nil, invalidID("requestId")
	}
	tenantID, responsibilityID, err := r.externalResponsibility(ctx)
	if err != nil {
		// Capture submission revokes the invitation. A retry may confirm an
		// already received RC1 with the same completed-capture credential, but
		// it must never regain mutation authority.
		credentials, ok := requestctx.ExternalCredentialsFromContext(ctx)
		if !ok {
			return nil, err
		}
		readResponsibility, readErr := r.Invitations.ValidateCaptureRead(ctx, credentials.SessionToken, credentials.CSRFToken)
		if readErr != nil || readResponsibility == (identity.ID{}) {
			return nil, err
		}
		readTenant, tenantErr := security.ParseScopedToken(credentials.SessionToken)
		if tenantErr != nil {
			return nil, err
		}
		var request database.RecaptureRequest
		lookupErr := withTask06Tenant(ctx, r.DB, readTenant, func(tx *gorm.DB) error {
			return tx.WithContext(ctx).Where("tenant_id=? AND id=? AND responsibility_id=? AND status='RECEIVED'", readTenant, requestID, readResponsibility).Take(&request).Error
		})
		if lookupErr != nil {
			if errors.Is(lookupErr, gorm.ErrRecordNotFound) {
				return nil, err
			}
			return nil, lookupErr
		}
		return &graphql1.RecapturePayload{Recapture: &graphql1.Recapture{ID: request.ID.String(), ResponsibilityID: request.ResponsibilityID.String(), Status: request.Status}, UserErrors: []*graphql1.UserError{}, ClientMutationID: input.ClientMutationID}, nil
	}
	raw, err := r.Bus.Send(ctx, recapturesubmit.Command{TenantID: tenantID, ResponsibilityID: responsibilityID, RequestID: requestID, ConfirmIncomplete: input.ConfirmIncomplete})
	if err != nil {
		return nil, err
	}
	result := raw.(recapturecore.Result)
	return &graphql1.RecapturePayload{Recapture: &graphql1.Recapture{ID: result.RequestID.String(), ResponsibilityID: result.ResponsibilityID.String(), Status: result.Status}, UserErrors: []*graphql1.UserError{}, ClientMutationID: input.ClientMutationID}, nil
}

// DeclareSensitiveDetectionFalsePositive is the resolver for the declareSensitiveDetectionFalsePositive field.
func (r *mutationResolver) DeclareSensitiveDetectionFalsePositive(ctx context.Context, input graphql1.SensitiveFalsePositiveInput) (*graphql1.MediaPayload, error) {
	if meta, ok := requestctx.FromContext(ctx); ok && meta.Principal.Internal {
		if err := internalRole(meta, auth.TenantAdmin, auth.Manager); err != nil {
			return nil, err
		}
		mediaID, err := identity.ParseID(input.MediaID)
		if err != nil {
			return nil, invalidID("mediaId")
		}
		var media database.MediaObject
		if r.DB == nil {
			return nil, apperror.New(apperror.DependencyUnavailable, "", "database unavailable")
		}
		err = withTask06Tenant(ctx, r.DB, meta.TenantID, func(tx *gorm.DB) error {
			return tx.WithContext(ctx).Where("tenant_id = ? AND id = ?", meta.TenantID, mediaID).Take(&media).Error
		})
		if err != nil {
			if err == gorm.ErrRecordNotFound {
				return nil, apperror.New(apperror.NotFound, "mediaId", "media not found")
			}
			return nil, err
		}
		resumeVideo := false
		if media.Status == "SCREENED" {
			var inspection database.Inspection
			if err := withTask06Tenant(ctx, r.DB, meta.TenantID, func(tx *gorm.DB) error {
				return tx.Table("inspections.inspections i").Select("i.*").Joins("JOIN inspections.responsibilities r ON r.tenant_id=i.tenant_id AND r.inspection_id=i.id").Where("i.tenant_id=? AND r.id=?", meta.TenantID, media.ResponsibilityID).Take(&inspection).Error
			}); err != nil {
				return nil, apperror.New(apperror.NotFound, "mediaId", "media not found")
			}
			if r.Authorizer.Store != nil || r.Authorizer.Scopes != nil {
				if _, authErr := r.Authorizer.Authorize(ctx, meta.TenantID, []string{auth.TenantAdmin, auth.Manager}, &requestctx.Scope{Kind: "INSPECTION", ID: inspection.ID}, true); authErr != nil {
					return nil, apperror.New(apperror.NotFound, "mediaId", "media not found")
				}
			} else if !inPrincipalScope(meta.Principal, inspection.BusinessUnitID) {
				return nil, apperror.New(apperror.NotFound, "mediaId", "media not found")
			}
			var draft database.CaptureDraft
			if err := withTask06Tenant(ctx, r.DB, meta.TenantID, func(tx *gorm.DB) error {
				return tx.Where("tenant_id=? AND responsibility_id=?", meta.TenantID, media.ResponsibilityID).Take(&draft).Error
			}); err != nil {
				return nil, err
			}
			resumeVideo = media.MediaKind == "VIDEO" && draft.Status == "SUBMITTED"
		}
		if resumeVideo {
			rawStatus, statusErr := r.Bus.Ask(ctx, mediavideoprep.Query{TenantID: meta.TenantID, MediaID: mediaID})
			if statusErr != nil {
				return nil, statusErr
			}
			if !rawStatus.(mediavideoprep.Status).SourceAvailable {
				return sensitiveFalsePositiveFailure(apperror.New(apperror.SourceUnavailable, "mediaId", "Vídeo original indisponível"), input.ClientMutationID)
			}
		}
		if media.Status == "SCREENED" {
			objectKey := media.ObjectKey
			if media.MediaKind == "PHOTO" {
				var derivative database.MediaDerivative
				if err := withTask06Tenant(ctx, r.DB, meta.TenantID, func(tx *gorm.DB) error {
					return tx.Where("tenant_id=? AND media_id=? AND kind='DISPLAY'", meta.TenantID, mediaID).Take(&derivative).Error
				}); err != nil {
					return sensitiveFalsePositiveFailure(apperror.New(apperror.SourceUnavailable, "mediaId", "Original indisponível"), input.ClientMutationID)
				}
				objectKey = derivative.ObjectKey
			}
			if r.Store.Client == nil {
				return sensitiveFalsePositiveFailure(apperror.New(apperror.SourceUnavailable, "mediaId", "Original indisponível"), input.ClientMutationID)
			}
			_, headErr := r.Store.Client.Head(ctx, r.Store.Bucket, objectKey)
			if headErr != nil {
				return sensitiveFalsePositiveFailure(apperror.New(apperror.SourceUnavailable, "mediaId", "Original indisponível"), input.ClientMutationID)
			}
		}
		raw, err := r.Bus.Send(ctx, mediafalsepositive.Command{TenantID: meta.TenantID, ResponsibilityID: media.ResponsibilityID, MediaID: mediaID, Reason: input.Reason})
		if err != nil {
			return sensitiveFalsePositiveFailure(err, input.ClientMutationID)
		}
		return &graphql1.MediaPayload{Media: mapMedia(raw.(database.MediaObject)), UserErrors: []*graphql1.UserError{}, ClientMutationID: input.ClientMutationID}, nil
	}
	return nil, apperror.New(apperror.Forbidden, "", "sensitive-content decisions require an internal reviewer")
}

// ConfigureRetentionPolicy is the resolver for the configureRetentionPolicy field.
func (r *mutationResolver) ConfigureRetentionPolicy(ctx context.Context, input graphql1.ConfigureRetentionPolicyInput) (*graphql1.RetentionPolicyPayload, error) {
	meta, ok := requestctx.FromContext(ctx)
	if !ok {
		return nil, unauthenticated()
	}
	if err := internalRole(meta, auth.TenantAdmin, auth.Manager, auth.Employee); err != nil {
		return nil, err
	}
	if input.EvidenceDays <= 0 || input.OperationalDays <= 0 || (input.SecurityDays != nil && *input.SecurityDays < 0) {
		field := "evidenceDays"
		if input.OperationalDays <= 0 {
			field = "operationalDays"
		} else if input.SecurityDays != nil && *input.SecurityDays < 0 {
			field = "securityDays"
		}
		return nil, graphql1Error(field)
	}
	securityDays := 0
	if input.SecurityDays != nil {
		securityDays = *input.SecurityDays
	}
	var row database.RetentionPolicy
	err := withTask06Tenant(ctx, r.DB, meta.TenantID, func(tx *gorm.DB) error {
		var previous database.RetentionPolicy
		version := int64(1)
		if err := tx.Session(&gorm.Session{}).Order("version DESC").First(&previous).Error; err == nil {
			version = previous.Version + 1
		} else if err != gorm.ErrRecordNotFound {
			return err
		}
		now := time.Now().UTC()
		row = database.RetentionPolicy{ID: identity.NewID(), TenantID: meta.TenantID, EvidenceDays: input.EvidenceDays, OperationalDays: input.OperationalDays, SecurityDays: securityDays, Version: version, CreatedAt: now, UpdatedAt: now}
		return tx.Session(&gorm.Session{}).Create(&row).Error
	})
	if err != nil {
		return nil, err
	}
	return &graphql1.RetentionPolicyPayload{Policy: mapRetentionPolicy(row), UserErrors: []*graphql1.UserError{}, ClientMutationID: input.ClientMutationID}, nil
}

// RecordDeletionRequest is the resolver for the recordDeletionRequest field.
func (r *mutationResolver) RecordDeletionRequest(ctx context.Context, input graphql1.RecordDeletionRequestInput) (*graphql1.RetentionMutationPayload, error) {
	meta, ok := requestctx.FromContext(ctx)
	if !ok {
		return nil, unauthenticated()
	}
	if err := internalRole(meta, auth.TenantAdmin, auth.Manager); err != nil {
		return nil, err
	}
	scope, err := parseRetentionScope(input.InspectionID, input.SourceMediaID, input.OriginVersionID)
	if err != nil {
		return nil, err
	}
	var row database.DeletionRequest
	if input.Reason != nil {
		row.Reason = *input.Reason
	}
	err = withTask06Tenant(ctx, r.DB, meta.TenantID, func(tx *gorm.DB) error {
		if err := lockRetentionScope(tx, meta.TenantID, scope); err != nil {
			return err
		}
		if err := rejectKnownDeletionBlock(tx, meta.TenantID, scope); err != nil {
			return err
		}
		var existing database.DeletionRequest
		if err := retentionScopeQuery(tx.Session(&gorm.Session{NewDB: true}).Model(&database.DeletionRequest{}).Where("tenant_id=?", meta.TenantID), scope).Where("status IN ('REQUESTED','REFUSED')").Order("requested_at DESC").First(&existing).Error; err == nil {
			row = existing
			return nil
		} else if err != gorm.ErrRecordNotFound {
			return err
		}
		now := time.Now().UTC()
		row = database.DeletionRequest{ID: identity.NewID(), TenantID: meta.TenantID, InspectionID: scope.inspectionID, SourceMediaID: scope.sourceMediaID, OriginVersionID: scope.originVersionID, Status: "REQUESTED", RequestedAt: now, Reason: row.Reason}
		return tx.Session(&gorm.Session{NewDB: true}).Create(&row).Error
	})
	if err != nil {
		return nil, err
	}
	id := row.ID.String()
	return &graphql1.RetentionMutationPayload{Status: row.Status, RequestID: &id, UserErrors: []*graphql1.UserError{}, ClientMutationID: input.ClientMutationID}, nil
}

