// VideoPreparations is the resolver for the videoPreparations field.
func (r *queryResolver) VideoPreparations(ctx context.Context, status []string, first *int, after *string) (*graphql1.VideoPreparationConnection, error) {
	meta, ok := requestctx.FromContext(ctx)
	if !ok {
		return nil, unauthenticated()
	}
	if err := internalRole(meta, auth.Manager, auth.Employee); err != nil {
		return nil, err
	}
	for _, value := range status {
		switch value {
		case "QUEUED", "PROCESSING", "FAILED", "READY":
		default:
			return nil, graphql1Error("status")
		}
	}
	limit, err := pageLimit(first)
	if err != nil {
		return nil, err
	}
	var cursorTime time.Time
	var cursorID identity.ID
	if after != nil && *after != "" {
		decoded, decodeErr := base64.RawURLEncoding.DecodeString(*after)
		parts := strings.Split(string(decoded), "|")
		if decodeErr != nil || len(parts) != 3 || parts[0] != meta.TenantID.String() {
			return nil, graphql1Error("after")
		}
		cursorTime, err = time.Parse(time.RFC3339Nano, parts[1])
		if err != nil {
			return nil, graphql1Error("after")
		}
		cursorID, err = identity.ParseID(parts[2])
		if err != nil {
			return nil, graphql1Error("after")
		}
	}
	if r.DB == nil {
		return nil, apperror.New(apperror.DependencyUnavailable, "", "database unavailable")
	}
	var jobs []database.VideoPreparationJob
	err = withTask06Tenant(ctx, r.DB, meta.TenantID, func(tx *gorm.DB) error {
		query := tx.WithContext(ctx).Where("tenant_id = ?", meta.TenantID)
		if len(status) > 0 {
			query = query.Where("status IN ?", status)
		}
		if !cursorTime.IsZero() {
			query = query.Where("created_at < ? OR (created_at = ? AND id < ?)", cursorTime, cursorTime, cursorID)
		}
		return query.Order("created_at DESC, id DESC").Limit(limit + 1).Find(&jobs).Error
	})
	if err != nil {
		return nil, err
	}
	more := len(jobs) > limit
	if more {
		jobs = jobs[:limit]
	}
	connection := &graphql1.VideoPreparationConnection{Nodes: make([]*graphql1.VideoPreparationStatus, 0, len(jobs)), PageInfo: pageInfo("", more)}
	err = withTask06Tenant(ctx, r.DB, meta.TenantID, func(tx *gorm.DB) error {
		for _, job := range jobs {
			item := &graphql1.VideoPreparationStatus{MediaID: job.MediaID.String(), PreparationID: job.ID.String(), Status: job.Status, Stage: job.Phase, PreparationVersion: job.PreparationVersion, Attempts: job.Attempts, ProcessedFrames: job.ProcessedFrames, ErrorCode: safeVideoPreparationError(job.ErrorCode), ManifestDigest: job.ManifestDigest}
			var source database.VideoSource
			sourceErr := tx.WithContext(ctx).Where("tenant_id = ? AND media_id = ?", meta.TenantID, job.MediaID).Take(&source).Error
			if sourceErr == nil {
				item.SourceAvailable = source.Status != "EXPIRED" && source.Status != "DELETING" && source.Status != "DELETED"
				if source.SourceExpiryAt != nil {
					value := source.SourceExpiryAt.UTC().Format(time.RFC3339Nano)
					item.SourceExpiryAt = &value
				}
			} else if sourceErr == gorm.ErrRecordNotFound {
				var media database.MediaObject
				if mediaErr := tx.WithContext(ctx).Where("tenant_id = ? AND id = ?", meta.TenantID, job.MediaID).Take(&media).Error; mediaErr == nil {
					item.SourceAvailable = media.ObjectKey != "" && media.Status != "EXPIRED" && media.Status != "DELETED" && media.Status != "REJECTED"
				} else if mediaErr != gorm.ErrRecordNotFound {
					return mediaErr
				}
			} else {
				return sourceErr
			}
			item.Retryable = job.Status == "FAILED" && item.SourceAvailable && source.ScreeningStatus != "BLOCKED"
			if job.FirstReadyAt != nil {
				value := job.FirstReadyAt.UTC().Format(time.RFC3339Nano)
				item.FirstFrameReadyAt = &value
				item.Stage = "READY"
			}
			connection.Nodes = append(connection.Nodes, item)
		}
		return nil
	})
	if err != nil {
		return nil, err
	}
	if len(jobs) > 0 {
		last := jobs[len(jobs)-1]
		cursor := base64.RawURLEncoding.EncodeToString([]byte(fmt.Sprintf("%s|%s|%s", meta.TenantID, last.CreatedAt.UTC().Format(time.RFC3339Nano), last.ID)))
		connection.PageInfo = pageInfo(cursor, more)
	}
	return connection, nil
}

// Reports is the resolver for the reports field.
func (r *queryResolver) Reports(ctx context.Context, first *int, after *string, search *string, classification *string) (*graphql1.ReportConnection, error) {
	meta, ok := requestctx.FromContext(ctx)
	if !ok {
		return nil, unauthenticated()
	}
	if err := internalRole(meta, auth.TenantAdmin, auth.Manager, auth.Employee, auth.Viewer); err != nil {
		return nil, err
	}
	if _, err := pageLimit(first); err != nil {
		return nil, err
	}
	input := listreports.Input{TenantID: meta.TenantID, TenantAdmin: hasRole(meta, auth.TenantAdmin)}
	for _, scope := range meta.Principal.Scopes {
		switch scope.Kind {
		case "BUSINESS_UNIT":
			input.Scopes = append(input.Scopes, scope.ID)
		case "ASSET":
			input.AssetScopes = append(input.AssetScopes, scope.ID)
		case "PROJECT":
			input.ProjectScopes = append(input.ProjectScopes, scope.ID)
		case "INSPECTION":
			input.InspectionScopes = append(input.InspectionScopes, scope.ID)
		}
	}
	if first != nil {
		input.First = *first
	}
	if after != nil {
		input.After = *after
	}
	if search != nil {
		input.Search = *search
	}
	if classification != nil {
		input.Classification = *classification
	}
	var result listreports.Result
	listOn := func(tx *gorm.DB) error {
		operation, setupErr := listreports.Setup(listreports.Dependencies{DB: tx})
		if setupErr != nil {
			return setupErr
		}
		value, operationErr := operation(ctx, input)
		result = value
		return operationErr
	}
	var err error
	if r.DB.Dialector.Name() == "postgres" {
		err = withTask06Tenant(ctx, r.DB, meta.TenantID, listOn)
	} else {
		err = listOn(r.DB)
	}
	if err != nil {
		if errors.Is(err, listreports.ErrInvalidCursor) {
			return nil, graphql1Error("after")
		}
		if errors.Is(err, listreports.ErrInvalidClassification) {
			return nil, graphql1Error("classification")
		}
		return nil, err
	}
	nodes := make([]*graphql1.ReportSummary, 0, len(result.Items))
	for _, item := range result.Items {
		nodes = append(nodes, &graphql1.ReportSummary{ID: item.ID.String(), InspectionID: item.InspectionID.String(), AssetName: item.AssetName, AssetAddress: item.AssetAddress, AssetExternalKey: item.AssetExternalKey, ParticipantName: item.ParticipantName, GeneratedAt: item.GeneratedAt.UTC().Format(time.RFC3339Nano), Classification: item.Classification, Version: item.Version})
	}
	return &graphql1.ReportConnection{Nodes: nodes, PageInfo: pageInfo(result.EndCursor, result.HasNextPage)}, nil
}

// ReportDownload is the resolver for the reportDownload field.
func (r *queryResolver) ReportDownload(ctx context.Context, snapshotID string, kind *string) (*graphql1.ReportDownload, error) {
	meta, ok := requestctx.FromContext(ctx)
	if !ok {
		return nil, unauthenticated()
	}
	id, err := identity.ParseID(snapshotID)
	if err != nil {
		return nil, invalidID("snapshotId")
	}
	value := "PDF"
	if kind != nil && *kind != "" {
		value = *kind
	}
	isCustomer := hasRole(meta, auth.CustomerViewer)
	if isCustomer {
		value = "PDF_CUSTOMER"
	} else if err := internalRole(meta, auth.TenantAdmin, auth.Manager, auth.Employee, auth.Viewer); err != nil {
		return nil, err
	} else if value != "PDF" && value != "PDF_CUSTOMER" && value != "HTML" {
		return nil, graphql1Error("kind")
	}
	var snapshot database.ReportSnapshot
	if err := withTask06Tenant(ctx, r.DB, meta.TenantID, func(tx *gorm.DB) error {
		return tx.Where("id=?", id).Take(&snapshot).Error
	}); errors.Is(err, gorm.ErrRecordNotFound) {
		return nil, apperror.New(apperror.NotFound, "snapshotId", "report not found")
	} else if err != nil {
		return nil, err
	}
	if err := authorizeReportInspection(ctx, r.DB, meta, snapshot.InspectionID); err != nil {
		return nil, err
	}
	var row database.ReportArtifact
	status := ""
	kindOut := value
	if isCustomer {
		kindOut = "PDF" // customers always request the published PDF by its public kind
	}
	if err := withTask06Tenant(ctx, r.DB, meta.TenantID, func(tx *gorm.DB) error {
		if isCustomer {
			var publication database.ReportPublication
			if err := tx.Where("tenant_id=? AND snapshot_id=? AND status='PUBLISHED'", meta.TenantID, id).First(&publication).Error; errors.Is(err, gorm.ErrRecordNotFound) {
				// Unpublished or revoked releases are undisclosed to customers.
				return apperror.New(apperror.NotFound, "snapshotId", "report not found")
			} else if err != nil {
				return err
			}
		}
		if err := tx.Where("snapshot_id=? AND kind=?", id, value).First(&row).Error; err != nil {
			if !errors.Is(err, gorm.ErrRecordNotFound) {
				return err
			}
			if snapshot.PDFRenderVersion == 1 && (value == "PDF" || value == "PDF_CUSTOMER") {
				status, err = reportPDFJobStatusTx(tx, meta.TenantID, id, value)
				if err != nil {
					return err
				}
			} else {
				var fallback database.ReportArtifact
				if fallbackErr := tx.Where("snapshot_id=? AND kind='HTML'", id).First(&fallback).Error; fallbackErr == nil {
					status = "FAILED"
				} else if !errors.Is(fallbackErr, gorm.ErrRecordNotFound) {
					return fallbackErr
				} else {
					status = "PENDING"
				}
			}
		}
		return nil
	}); err != nil {
		return nil, err
	}
	if status != "" {
		return &graphql1.ReportDownload{SnapshotID: id.String(), Kind: kindOut, ObjectKey: "", Status: status, URL: ""}, nil
	}
	url := ""
	if r.Store.Client != nil {
		signed, signErr := r.Store.PresignGet(ctx, row.ObjectKey, 5*time.Minute)
		if signErr != nil {
			return nil, apperror.New(apperror.DependencyUnavailable, "store", "report download is unavailable")
		}
		url = signed
	}
	return &graphql1.ReportDownload{SnapshotID: row.SnapshotID.String(), Kind: kindOut, ObjectKey: "", Status: row.Status, URL: url, Sha256: strptr(row.SHA256)}, nil
}

// DashboardSummary is the resolver for the dashboardSummary field.
func (r *queryResolver) DashboardSummary(ctx context.Context, projectID *string, businessUnitID *string) (*graphql1.DashboardSummary, error) {
	meta, ok := requestctx.FromContext(ctx)
	if !ok {
		return nil, unauthenticated()
	}
	var rows []database.DashboardInspection
	err := withTask06Tenant(ctx, r.DB, meta.TenantID, func(tx *gorm.DB) error {
		query := tx
		if projectID != nil {
			id, err := identity.ParseID(*projectID)
			if err != nil {
				return invalidID("projectId")
			}
			query = query.Where("project_id=?", id)
		}
		if businessUnitID != nil {
			id, err := identity.ParseID(*businessUnitID)
			if err != nil {
				return invalidID("businessUnitId")
			}
			query = query.Joins("JOIN inspections.inspections i ON i.id=dashboard.inspections.inspection_id AND i.tenant_id=dashboard.inspections.tenant_id").Where("i.business_unit_id=?", id)
		}
		return query.Find(&rows).Error
	})
	if err != nil {
		return nil, err
	}
	result := &graphql1.DashboardSummary{}
	for _, row := range rows {
		result.Total++
		if row.Invalidated {
			result.Invalidated++
			continue
		}
		switch row.Classification {
		case "NORMAL":
			result.Normal++
		case "CRITICAL":
			result.Critical++
		case "ATTENTION":
			result.Attention++
		}
		if row.Status != "COMPLETED" {
			result.Pending++
		}
	}
	return result, nil
}

// TriageInspections is the resolver for the triageInspections field.
func (r *queryResolver) TriageInspections(ctx context.Context, first *int, after *string, classification *string, status *string) (*graphql1.TriageInspectionConnection, error) {
	meta, ok := requestctx.FromContext(ctx)
	if !ok {
		return nil, unauthenticated()
	}
	limit := intValue(first)
	if limit <= 0 {
		limit = 25
	}
	if limit > 100 {
		limit = 100
	}
	if classification != nil && *classification != "" && *classification != "NORMAL" && *classification != "ATTENTION" && *classification != "CRITICAL" {
		return nil, graphql1Error("classification")
	}
	var rows []database.DashboardInspection
	err := withTask06Tenant(ctx, r.DB, meta.TenantID, func(tx *gorm.DB) error {
		query := tx.Where("invalidated=false")
		if after != nil && *after != "" {
			cursorBucket, cursorTime, cursorID, err := dashboardcore.DecodeTriageCursor(*after)
			if err != nil {
				// Accept the original timestamp/id cursor format for clients that
				// started paging before risk-priority cursors were introduced.
				legacyTime, legacyID, legacyErr := dashboardcore.DecodeCursor(*after)
				if legacyErr != nil {
					return invalidID("after")
				}
				cursorBucket, cursorTime, cursorID = 0, legacyTime, legacyID
			}
			prioritySQL := "CASE classification WHEN 'CRITICAL' THEN 0 WHEN 'ATTENTION' THEN 1 ELSE 2 END"
			query = query.Where("("+prioritySQL+" > ?) OR ("+prioritySQL+" = ? AND ((updated_at < ?) OR (updated_at = ? AND inspection_id < ?)))", cursorBucket, cursorBucket, cursorTime, cursorTime, cursorID)
		}
		if classification != nil && *classification != "" {
			query = query.Where("classification=?", *classification)
		}
		if status != nil && *status != "" {
			query = query.Where("status=?", *status)
		}
		return query.Order("CASE classification WHEN 'CRITICAL' THEN 0 WHEN 'ATTENTION' THEN 1 ELSE 2 END ASC, updated_at DESC, inspection_id DESC").Limit(limit + 1).Find(&rows).Error
	})
	if err != nil {
		return nil, err
	}
	hasNext := len(rows) > limit
	if hasNext {
		rows = rows[:limit]
	}
	nodes := make([]*graphql1.TriageInspection, 0, len(rows))
	for _, row := range rows {
		nodes = append(nodes, mapTriage(row))
	}
	end := ""
	if len(rows) > 0 {
		last := rows[len(rows)-1]
		end = dashboardcore.EncodeTriageCursor(dashboardcore.Projection{InspectionID: last.InspectionID.String(), Classification: last.Classification, UpdatedAt: last.UpdatedAt})
	}
	return &graphql1.TriageInspectionConnection{Nodes: nodes, PageInfo: pageInfo(end, hasNext)}, nil
}

