// ExternalCapture is the resolver for the externalCapture field.
func (r *queryResolver) ExternalCapture(ctx context.Context) (*graphql1.ExternalCapture, error) {
	tenantID, responsibilityID, err := r.externalResponsibility(ctx)
	if err != nil {
		if _, hasExternalCredentials := requestctx.ExternalCredentialsFromContext(ctx); !hasExternalCredentials {
			return nil, err
		}
		tenantID, responsibilityID, err = r.externalCaptureReadResponsibility(ctx)
		if err != nil {
			return nil, err
		}
	}
	raw, err := r.Bus.Ask(ctx, capturebootstrap.Query{TenantID: tenantID, ResponsibilityID: responsibilityID})
	if err != nil {
		return nil, err
	}
	view := raw.(capturecore.Bootstrap)
	reference, policy := map[string]any{}, map[string]any{}
	_ = json.Unmarshal(view.Draft.ReferencePayload, &reference)
	_ = json.Unmarshal(view.Draft.PolicyPayload, &policy)
	if view.Draft.MediaKind == "VIDEO" {
		if policy == nil {
			policy = map[string]any{}
		}
		rawPolicy, err := r.Bus.Ask(ctx, mediavideopolicy.CaptureQuery{TenantID: tenantID})
		if err != nil {
			return nil, err
		}
		videoPolicy := rawPolicy.(database.VideoPolicy)
		policy["maxDurationSeconds"] = videoPolicy.MaxDurationMinutes * 60
		policy["videoPolicyVersion"] = videoPolicy.Version
	}
	var captureLayout *string
	if !view.ConfirmationOnly && view.SchemaVersion >= 2 {
		value := "ENVIRONMENTS"
		captureLayout = &value
	}
	response := &graphql1.ExternalCapture{ResponsibilityID: responsibilityID.String(), Status: view.Draft.Status, ConfirmationOnly: view.ConfirmationOnly, Kind: view.Draft.Kind, MediaKind: view.Draft.MediaKind, TemplateVersionID: view.Draft.TemplateVersionID.String(), CaptureLayout: captureLayout, Reference: reference, ReferenceItems: []*graphql1.CaptureReferenceItem{}, Policy: policy, Requirements: []*graphql1.CaptureRequirement{}, Environments: []*graphql1.CaptureEnvironment{}, Answers: []*graphql1.CaptureAnswer{}, DisclosureVersion: invitationcore.PrivacyDisclosureVersion}
	if view.Draft.Kind == "RECAPTURE" {
		var request database.RecaptureRequest
		if err := (tenanttx.Runner{DB: r.DB}).Within(ctx, tenantID, func(tx *gorm.DB) error {
			return tx.Where("tenant_id=? AND responsibility_id=?", tenantID, responsibilityID).First(&request).Error
		}); err != nil {
			return nil, err
		}
		requestID := request.ID.String()
		response.RecaptureRequestID = &requestID
		deadline := request.DeadlineAt.UTC().Format(time.RFC3339Nano)
		response.RecaptureDeadlineAt = &deadline
	}
	if view.Draft.Kind == "VIDEO_REPLACEMENT" {
		var replacement database.VideoReplacement
		if err := (tenanttx.Runner{DB: r.DB}).Within(ctx, tenantID, func(tx *gorm.DB) error {
			return tx.Where("tenant_id=? AND responsibility_id=?", tenantID, responsibilityID).First(&replacement).Error
		}); err != nil {
			return nil, err
		}
		deadline := replacement.DeadlineAt.UTC().Format(time.RFC3339Nano)
		response.ReplacementDeadlineAt = &deadline
	}
	if view.ConfirmationOnly {
		response.Status = "CONFIRMED"
		within := r.Invitations.Within
		if within == nil {
			within = (tenanttx.Runner{DB: r.DB}).Within
		}
		var invitation database.Invitation
		if err := within(ctx, tenantID, func(tx *gorm.DB) error {
			return tx.Where("tenant_id=? AND responsibility_id=?", tenantID, responsibilityID).Order("created_at DESC").Take(&invitation).Error
		}); err != nil && !errors.Is(err, gorm.ErrRecordNotFound) {
			return nil, err
		}
		if invitation.ReviewerMembershipID != nil {
			inspectionID := responsibilityID
			var originVersion database.OriginVersion
			if err := within(ctx, tenantID, func(tx *gorm.DB) error {
				var responsibility database.Responsibility
				if err := tx.Where("tenant_id=? AND id=?", tenantID, responsibilityID).Take(&responsibility).Error; err == nil {
					inspectionID = responsibility.InspectionID
				} else if !errors.Is(err, gorm.ErrRecordNotFound) {
					return err
				}
				err := tx.Where("tenant_id=? AND has_inventory=true AND status='DRAFT' AND (responsibility_id=? OR source_inspection_id=?)", tenantID, responsibilityID, inspectionID).Order("created_at DESC,id DESC").Take(&originVersion).Error
				if errors.Is(err, gorm.ErrRecordNotFound) {
					return nil
				}
				return err
			}); err != nil {
				return nil, err
			}
			var draftOriginID *identity.ID
			if originVersion.ID != (identity.ID{}) {
				draftOriginID = &originVersion.ID
			}
			response.ReviewHandoff = captureReviewHandoff(invitation, inspectionID, draftOriginID)
		}
		return response, nil
	}
	accepted, err := r.Invitations.HasProcessingAcceptance(ctx, tenantID, responsibilityID)
	if err != nil {
		return nil, err
	}
	if !accepted {
		response.Status = "ACCEPTANCE_REQUIRED"
		return response, nil
	}
	referencesRaw, err := r.Bus.Ask(ctx, capturereferences.Query{TenantID: tenantID, ResponsibilityID: responsibilityID})
	if err != nil {
		return nil, err
	}
	for _, item := range referencesRaw.([]capturereferences.Item) {
		mapped := &graphql1.CaptureReferenceItem{MediaID: item.MediaID.String(), RequirementKey: item.RequirementKey, Description: item.Description, Availability: item.Availability}
		if item.Reason != "" {
			value := item.Reason
			mapped.Reason = &value
		}
		if item.EvidenceID != (identity.ID{}) {
			value := item.EvidenceID.String()
			mapped.EvidenceID = &value
		}
		if item.SourceMediaID != (identity.ID{}) {
			value := item.SourceMediaID.String()
			mapped.SourceMediaID = &value
		}
		if item.TimestampMS != 0 {
			value := int(item.TimestampMS)
			mapped.TimestampMs = &value
		}
		if item.Environment != "" {
			value := item.Environment
			mapped.Environment = &value
		}
		if item.Component != "" {
			value := item.Component
			mapped.Component = &value
		}
		if item.View != "" {
			value := item.View
			mapped.View = &value
		}
		ambiguous, gap := item.Ambiguous, item.Gap
		mapped.Ambiguous, mapped.Gap = &ambiguous, &gap
		if item.ImageURL != "" {
			mapped.ImageURL = &item.ImageURL
		}
		if item.ImageURLExpiresAt != nil {
			expires := item.ImageURLExpiresAt.Format(time.RFC3339Nano)
			mapped.ImageURLExpiresAt = &expires
		}
		response.ReferenceItems = append(response.ReferenceItems, mapped)
	}
	requirements := make([]*graphql1.CaptureRequirement, 0, len(view.Requirements))
	for _, req := range view.Requirements {
		var instructions *string
		if req.Instructions != "" {
			value := req.Instructions
			instructions = &value
		}
		requirements = append(requirements, &graphql1.CaptureRequirement{
			Key: req.Key, Section: req.Section, Label: req.Label, Instructions: instructions,
			EvidenceKind: req.EvidenceKind, Required: req.Required,
			MinimumMedia: req.MinimumMedia, MaximumMedia: req.MaximumMedia,
			// Descriptions are optional in the capture experience. Keep the
			// GraphQL field for compatibility with older clients, but do not
			// advertise a legacy requirement as mandatory in the bootstrap.
			DescriptionRequired:  false,
			CaptureSourcePolicy:  req.CaptureSourcePolicy,
			ComparisonTarget:     req.ComparisonTarget,
			ImpossibilityAllowed: req.ImpossibilityAllowed,
		})
	}
	response.Environments = mapCaptureEnvironments(view)
	answers := make([]*graphql1.CaptureAnswer, 0, len(view.Answers))
	for _, row := range view.Answers {
		var ids []identity.ID
		_ = json.Unmarshal(row.MediaIDs, &ids)
		mapped := make([]string, 0, len(ids))
		for _, id := range ids {
			mapped = append(mapped, id.String())
		}
		reason := row.ImpossibilityReason
		answers = append(answers, &graphql1.CaptureAnswer{RequirementKey: row.RequirementKey, MediaIds: mapped, ImpossibilityReason: &reason, Version: int(row.Version)})
	}
	status := view.Draft.Status
	if view.ConfirmationOnly {
		status = "CONFIRMED"
	}
	response.Status, response.Requirements, response.Answers = status, requirements, answers
	return response, nil
}

